function hashIndex(key: string, mod: number): number {
  let h = 0;
  for (let i = 0; i < key.length; i++) {
    h = (h * 31 + key.charCodeAt(i)) >>> 0;
  }
  return h % mod;
}

const LOCATION_HEADING_TEMPLATES: ((n: string) => string)[] = [
  (n) => `Wedding safa planning for ${n}`,
  (n) => `A wedding safa wala's guide to ${n}`,
  (n) => `Booking wedding safa tying in ${n}`,
  (n) => `Groom pagdi and safa tying, planned for ${n}`,
  (n) => `${n}: your wedding safa booking guide`,
];

const LOCATION_INTRO_TEMPLATES: ((n: string) => string)[] = [
  (n) => `This ${n} guide combines local preparation needs with high-intent wedding safa, groom pagdi and baraati safa searches from our keyword research.`,
  (n) => `Families searching for a wedding safa wala in ${n} usually ask the same handful of questions — this guide answers them together.`,
  (n) => `Before booking wedding safa tying in ${n}, it helps to know what a local safa wala actually needs from you to plan the day well.`,
  (n) => `${n} weddings each have their own venue and guest pattern, so this guide covers what a wedding safa wala in ${n} plans around.`,
  (n) => `A short, practical guide to groom pagdi styling and wedding safa tying for couples planning a celebration in ${n}.`,
];

const LOCATION_BLOCK_TITLE_SETS: ((n: string) => [string, string, string])[] = [
  (n) => [`Wedding safa service in ${n}`, `Groom pagdi styles for ${n}`, `Booking and safa packages in ${n}`],
  (n) => [`How wedding safa tying works in ${n}`, `Colour and fabric choices in ${n}`, `What to share when booking in ${n}`],
  (n) => [`Safa wala service for ${n} weddings`, `Groom pagdi options in ${n}`, `Planning your ${n} safa booking`],
  (n) => [`On-location safa tying in ${n}`, `Styling the groom pagdi for ${n}`, `${n} booking checklist`],
];

function makeContent(pageName: string, profile: [string, string, string], isLocation: boolean): PageSeoContent {
  if (isLocation) {
    const heading = LOCATION_HEADING_TEMPLATES[hashIndex(`heading|${pageName}`, LOCATION_HEADING_TEMPLATES.length)](pageName);
    const introduction = LOCATION_INTRO_TEMPLATES[hashIndex(`intro|${pageName}`, LOCATION_INTRO_TEMPLATES.length)](pageName);
    const [t1, t2, t3] = LOCATION_BLOCK_TITLE_SETS[hashIndex(`blocks|${pageName}`, LOCATION_BLOCK_TITLE_SETS.length)](pageName);
    return {
      heading,
      introduction,
      blocks: [
        { title: t1, body: profile[0] },
        { title: t2, body: profile[1] },
        { title: t3, body: profile[2] },
      ],
    };
  }
  return {
    heading: `${pageName}: styles, packages and booking guidance`,
    introduction: `A practical guide built around the service terms couples and families use when comparing professional safa tying.`,
    blocks: [
      { title: "What the service includes", body: profile[0] },
      { title: "Styles, colours and finishing", body: profile[1] },
      { title: "Price, packages and booking", body: profile[2] },
    ],
  };
}

export function getLocationSeoContent(slug: string, name: string): PageSeoContent {
  const profile = locationProfiles[slug];
  if (!profile) throw new Error(`Missing SEO content profile for location: ${slug}`);
  return makeContent(name, profile, true);
}

export function getServiceSeoContent(slug: string, name: string): PageSeoContent {
  const profile = serviceProfiles[slug];
  if (!profile) throw new Error(`Missing SEO content profile for service: ${slug}`);
  return makeContent(name, profile, false);
}
